import type { OmarchyColors } from "@/features/material/colors";
import { makeThemeFileWriter } from "../shared";
import { hexFromArgb } from "@material/material-color-utilities";
import { flow } from "effect";

export const writeHyprlandLua = makeThemeFileWriter(
  "hyprland.lua",
  (input: OmarchyColors) => /* lua */ `
--
-- Generated by Omaterial for Omarchy v4.
--

local omaterial_gaps_in     = 2
local omaterial_gaps_out    = 4
local omaterial_border_size = 1
local omaterial_window_gap = omaterial_gaps_out
local omaterial_tab_gap_above = omaterial_border_size
local omaterial_tab_gap_below = omaterial_window_gap // 2
local omaterial_tab_gap_between = omaterial_window_gap // 2
local omaterial_tab_active_bg = "${hexToHyprlandRgb(input.accent)}"
local omaterial_tab_active_text = "${hexToHyprlandRgb(input.dark_background)}"
local omaterial_tab_inactive_bg = "${hexToHyprlandRgb(input.lighter_background)}"
local omaterial_tab_inactive_text = "${hexToHyprlandRgb(input.light_foreground)}"
local omaterial_tab_locked_bg = "${hexToHyprlandRgb(input.selection)}"
local omaterial_tab_locked_dim_bg = "${hexToHyprlandRgb(input.muted)}"
local omaterial_border_active = "${hexToHyprlandRgb(input.accent)}"
local omaterial_border_inactive = "${hexToHyprlandRgb(input.muted)}"

-- Direction the light comes from, in degrees: 0 = right, 90 = top,
-- counter-clockwise. The shadow is cast on the opposite side.
local omaterial_light_angle = 90
local omaterial_shadow_distance = 8
local omaterial_shadow_vector = {
  -math.cos(math.rad(omaterial_light_angle)) * omaterial_shadow_distance,
  math.sin(math.rad(omaterial_light_angle)) * omaterial_shadow_distance, -- screen y points down
}

hl.config({
  general = {
    gaps_in = omaterial_gaps_in,
    gaps_out = omaterial_gaps_out,
    border_size = omaterial_border_size,
    col = {
      active_border = { colors = { "${flow(hexFromArgb, hexToHyprlandRgb)(input.omaterial_primary)}", "${flow(hexFromArgb, hexToHyprlandRgb)(input.omaterial_outline)}" }, angle = 55 },
      inactive_border = "${flow(hexFromArgb, hexToHyprlandRgb)(input.omaterial_outlineVariant)}"
    },
  },

  group = {
    col = {
      border_active = { colors = { "${flow(hexFromArgb, hexToHyprlandRgb)(input.omaterial_primary)}", "${flow(hexFromArgb, hexToHyprlandRgb)(input.omaterial_outline)}" }, angle = 55 },
      border_inactive = "${flow(hexFromArgb, hexToHyprlandRgb)(input.omaterial_outlineVariant)}",
    },
  },

  decoration = {
    blur = {
      enabled = true,
      size = 6,
      passes = 3,
      popups = true
    },
    shadow = {
      enabled = true,
      color = "${flow(hexFromArgb, (hex) => hex + "4d", hexToHyprlandRgb)(input.omaterial_shadow)}",
      color_inactive = "${flow(hexFromArgb, (hex) => hex + "1a", hexToHyprlandRgb)(input.omaterial_shadow)}",
      range = 60,
      offset = omaterial_shadow_vector,
      render_power = 4,
      scale = 1
    }
  },

  group = {
    groupbar = {
      enabled = true,
      render_titles = true,
      height = 24,
      gaps_in = omaterial_tab_gap_between,  -- horizontal gap between tabs (2)
      keep_upper_gap = false,
      gaps_out = 2,
      indicator_height = 0,
      indicator_gap = omaterial_tab_gap_below - omaterial_tab_gap_above,
      text_padding = 4,

      -- Fill: opaque gradient boxes, square corners.
      gradients = true,
      gradient_rounding = 0,
      gradient_round_only_edges = false,
      round_only_edges = false,
      blur = true,

      text_color = omaterial_tab_active_text,
      text_color_inactive = omaterial_tab_inactive_text,
      col = {
        active = omaterial_tab_active_bg,
        inactive = omaterial_tab_inactive_bg,
        locked_active = omaterial_tab_locked_bg,
        locked_inactive = omaterial_tab_locked_dim_bg,
      },
    },
  }
})

-- Bar panels open as the omarchy-keyboard-panel layer; tooltips are popups
-- of omarchy-bar. ignore_alpha keeps the transparent parts unblurred.
hl.layer_rule({
  match = { namespace = "^(omarchy-bar|omarchy-keyboard-panel)$" },
  blur = true,
  blur_popups = true,
  ignore_alpha = 0.2,
})

-- Smart gaps: drop the gaps when only one tiled window is visible.
hl.workspace_rule({ workspace = "w[tv1]", gaps_out = 0, gaps_in = 0 })
hl.workspace_rule({ workspace = "f[1]",   gaps_out = 0, gaps_in = 0 })

-- Drop border and rounding on lone window so it sits flush against the edges.
hl.window_rule({
  match = { float = false, workspace = "w[tv1]" },
  border_size = 0,
  rounding = 0,
})

hl.window_rule({
  match = { float = false, workspace = "f[1]" },
  border_size = 0,
  rounding = 0,
})
`,
);

const hexToHyprlandRgb = (hex: string) => {
  const code = hex.replace(/^#/, "");
  return code.length === 6 ? `rgb(${code})` : `rgba(${code})`;
};
